sp_widget.client_script:
api.controller = function($scope, $timeout) {
    var c = this;

    // Load dashboard data from the server
    $scope.dashboardStats = c.data.dashboardStats;

    // Function to animate numbers
    function animateNumber(id, targetValue) {
        var current = 0;
        var increment = Math.ceil(targetValue / 50);
        var interval = setInterval(function() {
            current += increment;
            if (current >= targetValue) {
                current = targetValue;
                clearInterval(interval);
            }
            document.getElementById(id).innerText = current;
        }, 20);
    }

    // Apply animation when data is loaded
    $timeout(function() {
        animateNumber("totalOnboarding", $scope.dashboardStats.totalOnboarding);
        animateNumber("pendingOnboarding", $scope.dashboardStats.pendingOnboarding);
        animateNumber("completedOnboarding", $scope.dashboardStats.completedOnboarding);
        animateNumber("totalOffboarding", $scope.dashboardStats.totalOffboarding);
        animateNumber("pendingOffboarding", $scope.dashboardStats.pendingOffboarding);
        animateNumber("completedOffboarding", $scope.dashboardStats.completedOffboarding);
    }, 500);
};

sp_widget.css:
.dashboard-container {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 15px;
    padding: 20px;
}

.dashboard-card {
    background: #fff;
    border-radius: 10px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    padding: 20px;
    text-align: center;
    flex: 1;
    min-width: 200px;
    transition: transform 0.3s ease-in-out;
}

.dashboard-card:hover {
    transform: translateY(-5px);
}

.dashboard-card i {
    font-size: 30px;
    color: #4a90e2;
}

.dashboard-card h3 {
    font-size: 18px;
    margin: 10px 0;
}

.dashboard-card p {
    font-size: 24px;
    font-weight: bold;
    margin: 0;
}

/* Color Themes */
.onboarding { background: #e3f2fd; }
.offboarding { background: #ffebee; }
.pending { background: #fff3e0; }
.completed { background: #e8f5e9; }

sp_widget.script:
(function() {
    var result = {};

    // Fetch total onboarding requests
    var onboardingGR = new GlideAggregate('x_1583423_hr_hroo_employee_onboarding'); // Update table name
    onboardingGR.addAggregate('COUNT');
    onboardingGR.query();
    if (onboardingGR.next()) {
        result.totalOnboarding = onboardingGR.getAggregate('COUNT');
    }

    // Fetch total offboarding requests
    var offboardingGR = new GlideAggregate('x_1583423_hr_hroo_employee_offboarding'); // Update table name
    offboardingGR.addAggregate('COUNT');
    offboardingGR.query();
    if (offboardingGR.next()) {
        result.totalOffboarding = offboardingGR.getAggregate('COUNT');
    }

    // Fetch pending onboarding requests
    var pendingOnboardingGR = new GlideAggregate('x_1583423_hr_hroo_employee_onboarding');
    pendingOnboardingGR.addQuery('status', 'Pending'); // Adjust status field as per your table
    pendingOnboardingGR.addAggregate('COUNT');
    pendingOnboardingGR.query();
    if (pendingOnboardingGR.next()) {
        result.pendingOnboarding = pendingOnboardingGR.getAggregate('COUNT');
    }

    // Fetch completed onboarding requests
    var completedOnboardingGR = new GlideAggregate('x_1583423_hr_hroo_employee_onboarding');
    completedOnboardingGR.addQuery('status', 'Completed'); // Adjust status field as per your table
    completedOnboardingGR.addAggregate('COUNT');
    completedOnboardingGR.query();
    if (completedOnboardingGR.next()) {
        result.completedOnboarding = completedOnboardingGR.getAggregate('COUNT');
    }

    // Fetch pending offboarding requests
    var pendingOffboardingGR = new GlideAggregate('x_1583423_hr_hroo_employee_offboarding');
    pendingOffboardingGR.addQuery('status', 'Pending');
    pendingOffboardingGR.addAggregate('COUNT');
    pendingOffboardingGR.query();
    if (pendingOffboardingGR.next()) {
        result.pendingOffboarding = pendingOffboardingGR.getAggregate('COUNT');
    }

    // Fetch completed offboarding requests
    var completedOffboardingGR = new GlideAggregate('x_1583423_hr_hroo_employee_offboarding');
    completedOffboardingGR.addQuery('status', 'Completed');
    completedOffboardingGR.addAggregate('COUNT');
    completedOffboardingGR.query();
    if (completedOffboardingGR.next()) {
        result.completedOffboarding = completedOffboardingGR.getAggregate('COUNT');
    }

    // Send the data to the client script
    data.dashboardStats = result;
})();
